package com.abhiai.abhiai_backend.service;import java.util.UUID;import org.springframework.data.domain.PageRequest;import org.springframework.stereotype.Service;import com.abhiai.abhiai_backend.dto.ai.SocialSearchResponse;@Service public class SocialContentRetrievalService{private final SearchService search;public SocialContentRetrievalService(SearchService s){search=s;}public SocialSearchResponse retrieve(UUID user,String q){var posts=search.searchPosts(user,q,PageRequest.of(0,8)).content();return new SocialSearchResponse(q,posts,"Attributed public AbhiAI sources. AI summarization requires explicit provider consent and is not performed by this endpoint.");}}
